+template <typename T>
+const T* Type::as(bool (Type::*is_xxx)() const, const char* expected) const {
+  if (!(this->*is_xxx)()) {
+    stringStream ss;
+    this->dump_on(&ss);
+    assert((this->*is_xxx)(), "Not %s, got %s", expected, ss.as_string());
+  }
+  return static_cast<const T*>(this);
+}
